import type {
  EngineInterface,
  FsAncestor,
  InstructionFile,
  On,
  PluginOptions,
} from 'claude-code'

import Files from './files'
import Frames from './frames'
import Modes from './modes'
import Names from './names'
import Switches from './switches'
import Telemetry from './telemetry'

/**
 * No files: what a walk not taken, or one that failed, found.
 */
const NONE: readonly FsAncestor[] = []

/**
 * Registers the plugin's hooks for the mode `instructionFiles` names
 * (`claude-md-or-agents-md` when unset; the manifest lists the four, nothing
 * else arrives).
 *
 * `claude-md`: nothing beyond the usage row, the engine's CLAUDE.md walk
 * standing alone. `managed-only`: the project's and the person's instruction
 * files dropped, the organization's kept. `claude-md-or-agents-md` (a project
 * with none of its own) and `claude-md-and-agents-md`: AGENTS.md files joined
 * to the engine's instruction files, nested ones on a Read except in a run
 * where the engine attaches nothing to a turn (--bare, which sets
 * CLAUDE_CODE_SIMPLE, or CLAUDE_CODE_DISABLE_ATTACHMENTS). Every mode sends
 * its usage rows through `$.telemetry` where that noun is seated and drops
 * them where it is not.
 *
 * @param on the engine's registrar
 * @param options the plugin's options; `instructionFiles` is `claude-md`,
 * `claude-md-or-agents-md`, `claude-md-and-agents-md` or `managed-only`
 */
export function register(on: On, options: PluginOptions): void {
  const named = Modes.modeOf(options.instructionFiles)
  // COMPAT_BREAK(agents-md-project-instructions): drop the projectInstructions
  // mapping once stored settings have migrated. The host fills in the default,
  // so an instructionFiles set to it cannot be told from one left unset.
  const legacy = Modes.legacyModeOf(options.projectInstructions)
  const isLegacyRead = legacy !== undefined && named === Modes.DEFAULT_MODE
  const mode = isLegacyRead ? legacy : named
  let isRenameTold = legacy === undefined

  on('session.start', ($, e, next) => {
    Telemetry.quietly(() =>
      $.telemetry.log(Telemetry.modeRowOf(mode, e.isInteractive)),
    )

    if (!isRenameTold) {
      isRenameTold = true
      $.ui.log(
        isLegacyRead
          ? 'option projectInstructions in settings is honoured for now, ' +
              `read as instructionFiles ${mode}; set instructionFiles to ` +
              `${mode} and remove projectInstructions`
          : `option projectInstructions in settings is not read: ` +
              `instructionFiles ${mode} is set; remove projectInstructions`,
      )
    }

    return next(e)
  })

  if (mode === 'claude-md') {
    return
  }

  if (mode === 'managed-only') {
    on(
      'prompt.context',
      { instructionFiles: { kind: Files.DROPPED_KINDS } },
      ($, e, next) =>
        next({
          ...e,
          instructionFiles: e.instructionFiles?.filter(
            Files.isKeptWithoutInstructions,
          ),
        }),
    )

    return
  }

  const isFallback = mode === 'claude-md-or-agents-md'
  const given = new Map<string, Set<string>>()
  let inContext: readonly InstructionFile[] = []
  let home: string | undefined
  let isClaudeProject: boolean | undefined
  let rootSeen: string | undefined
  let rootLogged: string | undefined
  let isCounted = false

  on('prompt.context', async ($, e, next) => {
    const handed = e.instructionFiles

    if (handed === undefined) {
      return next(e).finally(() => {
        given.clear()
      })
    }

    const root = isFallback ? await $.session.root() : undefined
    rootSeen = root ?? rootSeen
    let isWalkFailed = false
    // The walk, not only what was handed: the engine can withhold a project
    // CLAUDE.md it loaded, and the project still has one.
    isClaudeProject =
      root !== undefined &&
      (handed.some(file => Files.isClaudeFileOnWalk(file, root)) ||
        (await $.fs.ancestors({ names: Names.CLAUDE_NAMES }).then(
          files => files.length > 0,
          () => {
            isWalkFailed = true

            return true
          },
        )))
    const found = isClaudeProject
      ? NONE
      : await $.fs.ancestors({ names: Names.AGENTS_NAMES }).catch(() => {
          isWalkFailed = true

          return NONE
        })
    const added = Files.unseenFiles(Files.filesOf(found), handed)

    if (!isCounted) {
      isCounted = true
      const counts = Telemetry.loadCountsOf(
        added,
        isClaudeProject && !isWalkFailed,
        isWalkFailed,
      )
      Telemetry.quietly(() =>
        $.telemetry.log(Telemetry.loadRowOf(mode, counts)),
      )
      Telemetry.quietly(() => $.telemetry.mark(Telemetry.loadMarkOf(counts)))
    }

    const isFirstLoad =
      root !== undefined && root !== rootLogged && added.length > 0

    if (isFirstLoad) {
      rootLogged = root
      $.ui.log(
        'no CLAUDE.md found; AGENTS.md loaded: ' +
          added
            .filter(file => file.parent === undefined)
            .map(file => file.path)
            .join(', '),
        { to: 'debug' },
      )
    }

    const instructionFiles = Files.withProjectFiles(handed, added)

    return next({ ...e, instructionFiles }).finally(() => {
      given.clear()
      inContext = instructionFiles
    })
  })

  on('agent.spawn', { fork: true }, async ($, e, next) => {
    const result = await next(e)

    if (result.agentId !== undefined) {
      const parent = given.get(e.parentAgentId ?? Names.MAIN_LOOP)
      given.set(result.agentId, new Set(parent))
    }

    return result
  })

  on('tool.call', { tool: 'Read' }, async ($, e, next) => {
    const result = await next(e)
    const isSettledElsewhere =
      e.tool !== 'Read' || result.deny !== undefined || result.isError

    if (isSettledElsewhere) {
      return result
    }

    if (!(await attachesOnRead($))) {
      return result
    }

    const [root, cwd] = await Promise.all([$.session.root(), $.session.cwd()])
    home ??= await homeOf($, cwd)
    const read = Frames.absoluteOf(e.file_path, cwd, home)

    if (root !== rootSeen) {
      rootSeen = root
      isClaudeProject = undefined
      given.clear()
    }

    isClaudeProject ??=
      isFallback &&
      (await $.fs.ancestors({ names: Names.CLAUDE_NAMES })).length > 0
    const isOutOfReach = isClaudeProject || !Frames.isBelow(read, root)

    if (isOutOfReach) {
      return result
    }

    const [stack, claude] = await Promise.all([
      $.fs.ancestors({ names: Names.AGENTS_NAMES, of: read, below: root }),
      $.fs.ancestors({ names: Names.CLAUDE_NAMES, of: read, below: root }),
    ]).catch((): [typeof NONE, typeof NONE] => [NONE, NONE])
    const loop = e.agentId ?? Names.MAIN_LOOP
    const sent = given.get(loop) ?? new Set<string>()
    given.set(loop, sent)
    const nested = (
      isFallback ? Frames.outsideClaudeDirs(stack, claude) : stack
    ).filter(file => Frames.isBelow(file.dir, root))
    const fresh = Files.unseenFiles(Files.filesOf(nested), [
      ...inContext,
      ...Files.filesOf(claude),
    ]).filter(file => !sent.has(file.path))
    const attached = fresh.filter(file => !Frames.isFileAt(file, read))
    const isWholeRead = e.offset === undefined && e.limit === undefined

    for (const file of fresh) {
      const isSent =
        attached.includes(file) || (Frames.isFileAt(file, read) && isWholeRead)

      if (isSent) {
        sent.add(file.path)
      }
    }

    const hasAttached = attached.length > 0

    if (hasAttached) {
      Telemetry.quietly(() =>
        $.telemetry.log(Telemetry.nestedRowOf(mode, attached.length)),
      )
    }

    return hasAttached
      ? {
          ...result,
          context: [
            ...(result.context ?? []),
            ...attached.map(Frames.nestedFrame),
          ],
        }
      : result
  })
}

/**
 * Whether a Read attaches nested AGENTS.md files in this run: not where the
 * engine attaches nothing to a turn, a nested CLAUDE.md included, which is a
 * --bare run (it sets CLAUDE_CODE_SIMPLE) or one with
 * CLAUDE_CODE_DISABLE_ATTACHMENTS on.
 *
 * Read on every Read, as the engine reads them on every turn: a settings
 * `env` block or a managed delivery can flip either mid-session. The files of
 * the walk itself need no such check: where the engine loads no instruction
 * files `$.fs.ancestors` finds none.
 *
 * @param $ the engine, as the `tool.call` hook holds it
 * @returns whether nested files ride a Read's result here
 */
async function attachesOnRead($: EngineInterface): Promise<boolean> {
  const [simple, attachmentsOff] = await Promise.all([
    $.env.get('CLAUDE_CODE_SIMPLE'),
    $.env.get('CLAUDE_CODE_DISABLE_ATTACHMENTS'),
  ])

  return (
    !Switches.isSwitchedOn(simple) && !Switches.isSwitchedOn(attachmentsOff)
  )
}

/**
 * The home directory a `~` in a Read's path stands for, read the way the
 * Read tool reads it.
 *
 * The profile directory on a Windows spelling of the working directory,
 * else `HOME`, each falling back to the other.
 *
 * @param $ the engine, as the `tool.call` hook holds it
 * @param cwd the session's working directory, whose spelling names the platform
 * @returns the home directory, or undefined when the environment names none
 */
async function homeOf(
  $: EngineInterface,
  cwd: string,
): Promise<string | undefined> {
  const [home, profile] = await Promise.all([
    $.env.get('HOME'),
    $.env.get('USERPROFILE'),
  ])
  const isWindowsSpelling = cwd.includes('\\')

  return isWindowsSpelling ? (profile ?? home) : (home ?? profile)
}

files.hooks/files/chain-root-of.ts:
import type { InstructionFile } from 'claude-code'

/**
 * The path of the file at the head of an instruction file's `@`-import
 * chain; the file's own path when nothing imported it.
 *
 * Follows `parent` among the given files until a file nothing imported.
 *
 * @param file the instruction file
 * @param byPath the files it may have come through, by path
 * @returns the chain head's path
 */
export function chainRootOf(
  file: InstructionFile,
  byPath: ReadonlyMap<string, InstructionFile>,
): string {
  const seen = new Set<string>([file.path])
  let path = file.path
  let parent = file.parent

  while (parent !== undefined && !seen.has(parent)) {
    seen.add(parent)
    path = parent
    parent = byPath.get(parent)?.parent
  }

  return path
}

files.hooks/files/insertion-index.ts:
import type { InstructionFile } from 'claude-code'

import Frames from '../frames'
import { chainRootOf } from './chain-root-of.js'
import { isProjectOwn } from './is-project-own.js'
import { projectDirOf } from './project-dir-of.js'

/**
 * Where a directory's AGENTS.md files go among the files the engine loaded,
 * as the engine orders project files root first.
 *
 * Before the first project file of a deeper directory (an imported file
 * counts with the file at the head of its chain), else after the last
 * project file, else before the engine's memory, else at the end.
 *
 * @param files the list so far
 * @param dir the directory the AGENTS.md files stand in
 * @returns the index to insert at
 */
export function insertionIndex(
  files: readonly InstructionFile[],
  dir: string,
): number {
  const byPath = new Map(files.map(file => [file.path, file]))
  const deeper = files.findIndex(
    file =>
      isProjectOwn(file) &&
      Frames.isBelow(projectDirOf(chainRootOf(file, byPath)), dir),
  )

  if (deeper !== -1) {
    return deeper
  }

  const lastOwn = files.findLastIndex(isProjectOwn)

  if (lastOwn !== -1) {
    return lastOwn + 1
  }

  const memory = files.findIndex(file => file.kind === 'memory')

  return memory === -1 ? files.length : memory
}

files.hooks/files/is-claude-file-on-walk.ts:
import type { InstructionFile } from 'claude-code'

import Frames from '../frames'
import Names from '../names'
import { isProjectOwn } from './is-project-own.js'
import { projectDirOf } from './project-dir-of.js'

/**
 * Whether a handed instruction file is a CLAUDE.md, `.claude/CLAUDE.md` or
 * CLAUDE.local.md of a directory on the walk down to the session's root.
 *
 * What makes a project "have a CLAUDE.md of its own" for
 * `claude-md-or-agents-md`, the same files the Read walk asks for; a rules
 * file, an imported file or an added directory's CLAUDE.md is not one.
 *
 * @param file the handed instruction file
 * @param root the session's project root, absolute
 * @returns true for the project's own CLAUDE.md files on the walk
 */
export function isClaudeFileOnWalk(
  file: InstructionFile,
  root: string,
): boolean {
  const isOwnClaudeFile =
    isProjectOwn(file) &&
    file.parent === undefined &&
    Names.CLAUDE_NAMES.some(name =>
      Frames.normalSpellingOf(file.path).endsWith(`/${name}`),
    )

  if (!isOwnClaudeFile) {
    return false
  }

  const dir = projectDirOf(file.path)
  const spelledRoot = Frames.normalSpellingOf(root)

  return dir === spelledRoot || Frames.isBelow(spelledRoot, dir)
}

files.hooks/files/project-dir-of.ts:
import Frames from '../frames'

/**
 * The project directory an instruction file speaks for: the directory
 * holding it, or the one holding its `.claude` folder.
 *
 * @param path the file's path, absolute
 * @returns the directory, in the walk's normal spelling
 */
export function projectDirOf(path: string): string {
  const spelled = Frames.normalSpellingOf(path)
  const claudeAt = spelled.lastIndexOf('/.claude/')
  const cut = claudeAt === -1 ? spelled.lastIndexOf('/') : claudeAt

  return cut <= 0 ? '/' : spelled.slice(0, cut)
}

files.hooks/files/unseen-files.ts:
import type { InstructionFile } from 'claude-code'

import Frames from '../frames'
import { isProjectOwn } from './is-project-own.js'

/**
 * The candidate files the engine has not already loaded, and no candidate
 * twice.
 *
 * Leaves out one whose path is among the handed files (a CLAUDE.md that
 * `@`-imports AGENTS.md) or whose text equals a handed project file's (a
 * CLAUDE.md symlinked to AGENTS.md); other kinds' text does not count.
 *
 * @param candidates the AGENTS.md instruction files of a walk
 * @param handed the files the engine handed the hook
 * @returns the candidates worth adding, in order
 */
export function unseenFiles(
  candidates: readonly InstructionFile[],
  handed: readonly InstructionFile[],
): InstructionFile[] {
  const paths = new Set(handed.map(file => Frames.normalSpellingOf(file.path)))
  const texts = new Set(
    handed.filter(isProjectOwn).map(file => file.content.trim()),
  )
  const kept: InstructionFile[] = []

  for (const file of candidates) {
    const path = Frames.normalSpellingOf(file.path)
    const text = file.content.trim()
    const isSeen = paths.has(path) || (text !== '' && texts.has(text))

    if (!isSeen) {
      paths.add(path)
      kept.push(file)
    }
  }

  return kept
}

files.hooks/files/with-project-files.ts:
import type { InstructionFile } from 'claude-code'

import { chainRootOf } from './chain-root-of.js'
import { insertionIndex } from './insertion-index.js'
import { projectDirOf } from './project-dir-of.js'

/**
 * The engine's instruction files with the AGENTS.md files placed where the
 * engine would place a project file of their directory; as is when none.
 *
 * @param handed the files the engine handed the hook, in its order
 * @param added the AGENTS.md instruction files to add, root first
 * @returns the merged list
 */
export function withProjectFiles(
  handed: readonly InstructionFile[],
  added: readonly InstructionFile[],
): readonly InstructionFile[] {
  if (added.length === 0) {
    return handed
  }

  const merged = [...handed]
  const byPath = new Map(added.map(file => [file.path, file]))
  const byDir = new Map<string, InstructionFile[]>()

  for (const file of added) {
    const dir = projectDirOf(chainRootOf(file, byPath))
    byDir.set(dir, [...(byDir.get(dir) ?? []), file])
  }

  for (const [dir, files] of byDir) {
    merged.splice(insertionIndex(merged, dir), 0, ...files)
  }

  return merged
}

files.hooks/frames/absolute-of.ts:
/**
 * A path the model handed a Read, made absolute as the Read tool reads it.
 *
 * As given when it is absolute; under the home directory (less any trailing
 * separator) for `~` or a `~/` spelling when a home is known; else under the
 * working directory.
 *
 * @param path the Read's `file_path` as the model spelled it
 * @param root the session's working directory, absolute
 * @param home the home directory, absolute, when the environment names one
 * @returns the absolute path
 */
export function absoluteOf(path: string, root: string, home?: string): string {
  const isHomeSpelling = path === '~' || path.startsWith('~/')

  if (isHomeSpelling && home !== undefined) {
    const bare = home.replace(/(?<=.)[\\/]+$/, '')

    return path === '~' ? bare : `${bare}${separatorOf(bare)}${path.slice(2)}`
  }

  return /^(?:[A-Za-z]:)?[\\/]/.test(path)
    ? path
    : `${root}${separatorOf(root)}${path}`
}

/**
 * The separator a directory's own spelling uses.
 *
 * @param dir an absolute directory
 * @returns `\` for a backslash spelling, `/` otherwise
 */
const separatorOf = (dir: string): string => (dir.includes('\\') ? '\\' : '/')

files.hooks/frames/outside-claude-dirs.ts:
import type { FsAncestor } from 'claude-code'

/**
 * The AGENTS.md files standing in a directory with no CLAUDE.md of its own,
 * in walk order.
 *
 * Where the engine attaches a directory's CLAUDE.md, that directory's
 * AGENTS.md is left out rather than merged.
 *
 * @param agents the AGENTS.md files of a walk, root first
 * @param claude the CLAUDE.md files of the same walk
 * @returns the AGENTS.md files whose directory holds no CLAUDE.md
 */
export function outsideClaudeDirs(
  agents: readonly FsAncestor[],
  claude: readonly FsAncestor[],
): readonly FsAncestor[] {
  const taken = new Set(claude.map(file => file.dir))

  return agents.filter(file => !taken.has(file.dir))
}

files.hooks/modes/legacy-mode-of.ts:
import type { Mode } from './types'

/**
 * Each value the option took under its old key, `projectInstructions`, and
 * the mode that keeps its meaning.
 */
const LEGACY_MODES: Readonly<Record<string, Mode>> = {
  none: 'managed-only',
  claude: 'claude-md',
  'agents-fallback': 'claude-md-or-agents-md',
  both: 'claude-md-and-agents-md',
}

/**
 * The mode a value stored under the old `projectInstructions` key keeps; a
 * value it never took reads as `claude-md`, which adds nothing, never as the
 * default, which loads AGENTS.md.
 *
 * COMPAT_BREAK(agents-md-project-instructions): drop the projectInstructions
 * mapping once stored settings have migrated.
 *
 * @param value the `projectInstructions` option as stored
 * @returns the mode it keeps, undefined when nothing is stored there
 */
export function legacyModeOf(value: unknown): Mode | undefined {
  if (value === undefined) {
    return undefined
  }

  return (
    (typeof value === 'string' ? LEGACY_MODES[value] : undefined) ?? 'claude-md'
  )
}

files.hooks/telemetry/load-counts-of.ts:
import type { InstructionFile } from 'claude-code'

import type { LoadCounts } from './types'

/**
 * The first context's counts from the files it added: an entry with a parent
 * is an `@` import, one without is an AGENTS.md file.
 *
 * @param added the AGENTS.md instruction files handed to the engine, imports
 * among them
 * @param isYielded whether `claude-md-or-agents-md` stood down for a CLAUDE.md
 * @param isWalkFailed whether the walk threw
 * @returns the counts the load row and mark are built from
 */
export function loadCountsOf(
  added: readonly InstructionFile[],
  isYielded: boolean,
  isWalkFailed: boolean,
): LoadCounts {
  const importCount = added.reduce(
    (sum, file) => sum + (file.parent === undefined ? 0 : 1),
    0,
  )

  return {
    fileCount: added.length - importCount,
    importCount,
    totalContentLength: added.reduce(
      (sum, file) => sum + file.content.length,
      0,
    ),
    isYielded,
    isWalkFailed,
  }
}

